import { isJsonValue, type JsonValue } from "./json-value.js";

/** Source sequence and observation time describe delivery, not event facts. */
export type TerminalStatus = "success" | "failure" | "cancel" | "interrupted";

export type RuntimeEventKind =
  | "fact"
  | "draft"
  | TerminalStatus
  | "operation_intent"
  | "operation_receipt";

/** Generic event scope may be incomplete; a turn projection requires a bound scope. */
export interface EventScope {
  readonly sessionId: string | null;
  readonly turnId: string | null;
  readonly runId: string | null;
  readonly taskId: string | null;
}

export interface BoundEventScope {
  readonly sessionId: string;
  readonly turnId: string;
  readonly runId: string;
  readonly taskId: string;
}

interface RuntimeEventFields<K extends RuntimeEventKind> {
  readonly source: string;
  readonly eventId: string;
  readonly scope: EventScope;
  readonly attemptId: string | null;
  readonly operationId: string | null;
  readonly kind: K;
  readonly occurredAt: string;
  readonly observedAt: string;
  /** Native 0 means unassigned and is normalized to null. */
  readonly sourceSequence: number | null;
  readonly payload: JsonValue;
}

type OperationEventKind = "operation_intent" | "operation_receipt";
type OrdinaryEventKind = Exclude<RuntimeEventKind, OperationEventKind>;

/** Operation intent/receipt events require a stable non-null operation ID. */
export type RuntimeEventInput =
  | RuntimeEventFields<OrdinaryEventKind>
  | (Omit<RuntimeEventFields<OperationEventKind>, "operationId"> & { readonly operationId: string });

/** Canonical facts deliberately exclude observedAt and sourceSequence. */
export type CanonicalEventFacts =
  | Omit<RuntimeEventFields<OrdinaryEventKind>, "observedAt" | "sourceSequence">
  | (Omit<RuntimeEventFields<OperationEventKind>, "operationId" | "observedAt" | "sourceSequence"> & { readonly operationId: string });

/** A validated, immutable event snapshot. Writer commit sequence is not a fact field. */
export type NormalizedEvent = RuntimeEventInput;

/** The writer's accepted-event receipt is separate from any operation-effect receipt. */
export interface WriterOrderedEvent {
  readonly commitSequence: number;
  readonly event: NormalizedEvent;
}

export interface SourceEventIdentity {
  readonly source: string;
  readonly eventId: string;
}

export interface OperationIntent {
  /** Stable across retries; attempt-scoped data is not part of this description. */
  readonly operationId: string;
  readonly occurredAt: string;
  readonly operation: string;
  readonly input: JsonValue;
}

/** External effect receipt; it does not prove that an event row was committed. */
/** An unknown receipt records uncertainty and does not authorize replay. */
export interface OperationReceipt {
  readonly operationId: string;
  readonly status: "success" | "failure" | "unknown";
  readonly observedAt: string;
  readonly result: JsonValue | null;
}

export interface AttemptProjectionTarget {
  readonly scope: BoundEventScope;
  readonly attemptId: string;
}

export interface EventReference extends SourceEventIdentity {
  readonly scope: EventScope;
  readonly attemptId: string | null;
}

export type EventAudit =
  | { readonly kind: "duplicate"; readonly event: EventReference }
  | {
      readonly kind: "redelivery_resequenced";
      readonly event: EventReference;
      readonly firstSourceSequence: number | null;
      readonly observedSourceSequence: number | null;
    }
  | { readonly kind: "identity_conflict"; readonly event: EventReference }
  | {
      readonly kind: "source_sequence_regressed";
      readonly event: EventReference;
      readonly priorMaximum: number;
      readonly observed: number;
    }
  | {
      readonly kind: "old_attempt";
      readonly event: EventReference;
      readonly currentAttemptId: string;
    }
  | {
      readonly kind: "after_terminal";
      readonly event: EventReference;
      readonly terminal: TerminalStatus;
    };

export interface AttemptTerminal {
  readonly status: TerminalStatus;
  readonly event: EventReference;
  readonly commitSequence: number;
  readonly occurredAt: string;
  /** Present only when the first success terminal carries an authoritative string response. */
  readonly authoritativeResponse: string | null;
}

export interface AttemptProjection {
  readonly attemptId: string;
  readonly lifecycle: TerminalStatus | "in_progress";
  readonly terminal: AttemptTerminal | null;
  readonly authoritativeResponse: string | null;
  readonly events: readonly NormalizedEvent[];
  readonly drafts: readonly NormalizedEvent[];
  readonly audit: readonly EventAudit[];
}

/** Rejects invalid source sequence values; native zero maps to unassigned null. */
export function normalizeSourceSequence(value: unknown): number | null {
  if (value === null) return null;
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 0) {
    throw new TypeError("sourceSequence must be null or a non-negative safe integer");
  }
  return value === 0 ? null : value;
}

/** Validates strict keys and snapshots payloads so later caller mutation cannot alter facts. */
export function normalizeRuntimeEvent(value: unknown): NormalizedEvent {
  if (!hasExactDataFields(value, EVENT_FIELDS)) {
    throw new TypeError("runtime event has invalid fields");
  }
  const record = value as Record<string, unknown>;
  const source = requireNonEmptyString(record.source, "source");
  const eventId = requireNonEmptyString(record.eventId, "eventId");
  const scope = normalizeEventScope(record.scope);
  const attemptId = normalizeNullableString(record.attemptId, "attemptId");
  const operationId = normalizeNullableString(record.operationId, "operationId");
  const kind = normalizeEventKind(record.kind);
  if ((kind === "operation_intent" || kind === "operation_receipt") && operationId === null) {
    throw new TypeError("operation events require a stable operationId");
  }
  const occurredAt = requireNonEmptyString(record.occurredAt, "occurredAt");
  const observedAt = requireNonEmptyString(record.observedAt, "observedAt");
  const sourceSequence = normalizeSourceSequence(record.sourceSequence);
  if (!isJsonValue(record.payload)) throw new TypeError("payload must be strict JsonValue");
  const payload = cloneAndFreezeJson(record.payload);

  return Object.freeze({
    source,
    eventId,
    scope,
    attemptId,
    operationId,
    kind,
    occurredAt,
    observedAt,
    sourceSequence,
    payload,
  }) as NormalizedEvent;
}

/** Canonical JSON with recursively sorted object keys. */
export function canonicalizeJson(value: JsonValue): string {
  if (!isJsonValue(value)) throw new TypeError("value must be strict JsonValue");
  return encodeCanonical(cloneAndFreezeJson(value));
}

/** Stable fact representation; observation metadata and writer sequence are excluded. */
export function canonicalizeEventFacts(event: NormalizedEvent): string {
  const normalized = normalizeRuntimeEvent(event);
  const facts = {
    source: normalized.source,
    eventId: normalized.eventId,
    scope: normalized.scope,
    attemptId: normalized.attemptId,
    operationId: normalized.operationId,
    kind: normalized.kind,
    occurredAt: normalized.occurredAt,
    payload: normalized.payload,
  } as unknown as CanonicalEventFacts;
  return canonicalizeJson(facts as unknown as JsonValue);
}

/**
 * Projects one explicitly bound attempt in writer commit order. Source sequence and
 * timestamps remain evidence; neither can reorder or replace the first terminal.
 */
export function projectAttempt(
  entries: readonly WriterOrderedEvent[],
  target: AttemptProjectionTarget,
): AttemptProjection {
  const normalizedTarget = normalizeProjectionTarget(target);
  if (!Array.isArray(entries)) throw new TypeError("writer events must be an array");

  const ordered: WriterOrderedEvent[] = [];
  const commitFacts = new Map<number, { readonly identity: string; readonly canonicalFacts: string }>();
  for (const entry of entries as readonly unknown[]) {
    if (!hasExactDataFields(entry, WRITER_EVENT_FIELDS)) {
      throw new TypeError("writer event must contain only commitSequence and event");
    }
    const record = entry as Record<string, unknown>;
    const commitSequence = record.commitSequence;
    if (typeof commitSequence !== "number" || !Number.isSafeInteger(commitSequence) || commitSequence <= 0) {
      throw new TypeError("commitSequence must be a positive safe integer");
    }
    const event = normalizeRuntimeEvent(record.event);
    assertBoundScope(event.scope, normalizedTarget.scope);
    const identity = identityKey(event);
    const canonicalFacts = canonicalizeEventFacts(event);
    const prior = commitFacts.get(commitSequence);
    if (prior !== undefined && (prior.identity !== identity || prior.canonicalFacts !== canonicalFacts)) {
      throw new TypeError("writer commit sequence collision between different facts");
    }
    commitFacts.set(commitSequence, { identity, canonicalFacts });
    ordered.push(Object.freeze({ commitSequence, event }));
  }
  ordered.sort((left, right) => left.commitSequence - right.commitSequence);

  const seen = new Map<string, { readonly canonicalFacts: string; readonly event: NormalizedEvent }>();
  const sourceSequenceMax = new Map<string, number>();
  const audit: EventAudit[] = [];
  const accepted: NormalizedEvent[] = [];
  const drafts: NormalizedEvent[] = [];
  let terminal: AttemptTerminal | null = null;

  for (const entry of ordered) {
    const event = entry.event;
    const reference = eventReference(event);
    if (event.sourceSequence !== null) {
      const priorMaximum = sourceSequenceMax.get(event.source);
      if (priorMaximum !== undefined && event.sourceSequence < priorMaximum) {
        audit.push(Object.freeze({
          kind: "source_sequence_regressed",
          event: reference,
          priorMaximum,
          observed: event.sourceSequence,
        }));
      }
      sourceSequenceMax.set(event.source, Math.max(priorMaximum ?? 0, event.sourceSequence));
    }

    const identity = identityKey(event);
    const canonicalFacts = canonicalizeEventFacts(event);
    const prior = seen.get(identity);
    if (prior !== undefined) {
      if (prior.canonicalFacts !== canonicalFacts) {
        audit.push(Object.freeze({ kind: "identity_conflict", event: reference }));
      } else {
        audit.push(Object.freeze({ kind: "duplicate", event: reference }));
        if (prior.event.sourceSequence !== event.sourceSequence) {
          audit.push(Object.freeze({
            kind: "redelivery_resequenced",
            event: reference,
            firstSourceSequence: prior.event.sourceSequence,
            observedSourceSequence: event.sourceSequence,
          }));
        }
      }
      continue;
    }
    seen.set(identity, { canonicalFacts, event });

    if (event.attemptId !== normalizedTarget.attemptId) {
      audit.push(Object.freeze({
        kind: "old_attempt",
        event: reference,
        currentAttemptId: normalizedTarget.attemptId,
      }));
      continue;
    }
    if (terminal !== null) {
      audit.push(Object.freeze({ kind: "after_terminal", event: reference, terminal: terminal.status }));
      continue;
    }

    accepted.push(event);
    if (event.kind === "draft") drafts.push(event);
    if (isTerminalStatus(event.kind)) {
      const authoritativeResponse = event.kind === "success" ? readResponse(event.payload) : null;
      terminal = Object.freeze({
        status: event.kind,
        event: reference,
        commitSequence: entry.commitSequence,
        occurredAt: event.occurredAt,
        authoritativeResponse,
      });
    }
  }

  return Object.freeze({
    attemptId: normalizedTarget.attemptId,
    lifecycle: terminal?.status ?? "in_progress",
    terminal,
    authoritativeResponse: terminal?.authoritativeResponse ?? null,
    events: Object.freeze(accepted),
    drafts: Object.freeze(drafts),
    audit: Object.freeze(audit),
  });
}

const EVENT_FIELDS = [
  "source", "eventId", "scope", "attemptId", "operationId", "kind",
  "occurredAt", "observedAt", "sourceSequence", "payload",
] as const;
const SCOPE_FIELDS = ["sessionId", "turnId", "runId", "taskId"] as const;
const WRITER_EVENT_FIELDS = ["commitSequence", "event"] as const;
const EVENT_KINDS = new Set<RuntimeEventKind>([
  "fact", "draft", "success", "failure", "cancel", "interrupted",
  "operation_intent", "operation_receipt",
]);
const TERMINAL_STATUSES = new Set<TerminalStatus>(["success", "failure", "cancel", "interrupted"]);

function hasExactDataFields(value: unknown, fields: readonly string[]): value is object {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
  try {
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) return false;
    const ownKeys = Reflect.ownKeys(value);
    if (ownKeys.length !== fields.length || ownKeys.some((key) => typeof key !== "string" || !fields.includes(key))) {
      return false;
    }
    return fields.every((field) => {
      const descriptor = Object.getOwnPropertyDescriptor(value, field);
      return descriptor !== undefined && descriptor.enumerable && "value" in descriptor;
    });
  } catch {
    return false;
  }
}

function normalizeEventScope(value: unknown): EventScope {
  if (!hasExactDataFields(value, SCOPE_FIELDS)) throw new TypeError("scope has invalid fields");
  const record = value as Record<string, unknown>;
  const normalized = Object.create(null) as Record<string, string | null>;
  for (const field of SCOPE_FIELDS) normalized[field] = normalizeNullableString(record[field], field);
  return Object.freeze(normalized) as unknown as EventScope;
}

function normalizeProjectionTarget(value: AttemptProjectionTarget): {
  readonly scope: BoundEventScope;
  readonly attemptId: string;
} {
  if (!hasExactDataFields(value, ["scope", "attemptId"])) {
    throw new TypeError("projection target has invalid fields");
  }
  const record = value as unknown as Record<string, unknown>;
  const scopeValue = record.scope;
  if (!hasExactDataFields(scopeValue, SCOPE_FIELDS)) throw new TypeError("projection scope has invalid fields");
  const sourceScope = scopeValue as Record<string, unknown>;
  const scope = Object.create(null) as Record<string, string>;
  for (const field of SCOPE_FIELDS) scope[field] = requireNonEmptyString(sourceScope[field], field);
  return Object.freeze({
    scope: Object.freeze(scope) as unknown as BoundEventScope,
    attemptId: requireNonEmptyString(record.attemptId, "attemptId"),
  });
}

function assertBoundScope(actual: EventScope, expected: BoundEventScope): void {
  for (const field of SCOPE_FIELDS) {
    if (actual[field] !== expected[field]) throw new TypeError(`event scope does not match projection ${field}`);
  }
}

function normalizeNullableString(value: unknown, label: string): string | null {
  if (value === null) return null;
  return requireNonEmptyString(value, label);
}

function requireNonEmptyString(value: unknown, label: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function normalizeEventKind(value: unknown): RuntimeEventKind {
  if (typeof value !== "string" || !EVENT_KINDS.has(value as RuntimeEventKind)) {
    throw new TypeError("runtime event kind is unsupported");
  }
  return value as RuntimeEventKind;
}

function cloneAndFreezeJson(value: JsonValue): JsonValue {
  if (value === null || typeof value === "string" || typeof value === "boolean" || typeof value === "number") {
    return value;
  }
  if (Array.isArray(value)) {
    return Object.freeze(value.map((item) => cloneAndFreezeJson(item)));
  }
  const object = value as { readonly [key: string]: JsonValue };
  const clone = Object.create(null) as Record<string, JsonValue>;
  for (const key of Object.keys(object).sort()) clone[key] = cloneAndFreezeJson(object[key]!);
  return Object.freeze(clone);
}

function encodeCanonical(value: JsonValue): string {
  if (value === null || typeof value === "boolean" || typeof value === "string") return JSON.stringify(value);
  if (typeof value === "number") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(encodeCanonical).join(",")}]`;
  const object = value as { readonly [key: string]: JsonValue };
  const keys = Object.keys(object).sort();
  return `{${keys.map((key) => `${JSON.stringify(key)}:${encodeCanonical(object[key]!)}`).join(",")}}`;
}

function identityKey(event: SourceEventIdentity): string {
  return canonicalizeJson([event.source, event.eventId]);
}

function eventReference(event: NormalizedEvent): EventReference {
  return Object.freeze({
    source: event.source,
    eventId: event.eventId,
    scope: event.scope,
    attemptId: event.attemptId,
  });
}

function isTerminalStatus(value: RuntimeEventKind): value is TerminalStatus {
  return TERMINAL_STATUSES.has(value as TerminalStatus);
}

function readResponse(payload: JsonValue): string | null {
  if (payload === null || typeof payload !== "object" || Array.isArray(payload)) return null;
  const response = (payload as Record<string, JsonValue>).response;
  return typeof response === "string" ? response : null;
}

import { createHash } from "node:crypto";
import {
  closeSync,
  constants,
  fstatSync,
  lstatSync,
  openSync,
  readSync,
  realpathSync,
} from "node:fs";
import path from "node:path";
import { canonicalizeJson } from "../../../contracts/src/events.js";
import type { JsonValue } from "../../../contracts/src/json-value.js";

const MAX_TRANSCRIPT_BYTES = 512 * 1024;
const STATUS_LIMIT = 64;
const DEFAULT_MAX_PENDING = 32;

export type TranscriptHookEvent = "UserPromptSubmit" | "Stop";

export interface UserPromptSubmitTranscriptInput {
  readonly hookEventName: "UserPromptSubmit";
  readonly sessionId: string;
  readonly turnId: string;
  readonly transcriptPath: string;
  readonly prompt: string;
}

export interface StopTranscriptInput {
  readonly hookEventName: "Stop";
  readonly sessionId: string;
  readonly turnId: string;
  readonly transcriptPath: string;
  readonly responseText?: string;
  readonly responsePreview?: string;
}

export type TranscriptHookInput = UserPromptSubmitTranscriptInput | StopTranscriptInput;

export interface TranscriptHookTrace {
  readonly hookEventName: string;
  readonly sessionId: string;
  readonly turnId: string;
}

export interface CaptureTranscriptInput {
  readonly hookInput: TranscriptHookInput;
  readonly trace: TranscriptHookTrace;
  readonly ownedTempRoot: string;
  readonly sourcePin: string;
}

export type CaptureRejectionCode =
  | "invalid_input"
  | "trace_mismatch"
  | "outside_owned_temp"
  | "linked_path"
  | "not_regular_file"
  | "missing"
  | "unreadable"
  | "too_large"
  | "unstable_read"
  | "invalid_utf8"
  | "incomplete_line"
  | "malformed_jsonl"
  | "message_mismatch";

export interface TranscriptMessageSnapshot {
  readonly role: "user" | "assistant";
  readonly text: "[REDACTED]";
  readonly textBytes: number;
  readonly textSha256: string;
}

export interface TranscriptSnapshot {
  readonly schemaVersion: 1;
  readonly redactionVersion: "full-mask-v1";
  readonly messages: readonly TranscriptMessageSnapshot[];
}

export interface TranscriptOrigin {
  /** Relative to ownedTempRoot and retained only as historical provenance. */
  readonly temporaryLocator: string;
  readonly locatorUse: "historical-only";
  readonly rawBytes: number;
  readonly rawSha256: string;
  readonly sourcePin: string;
  readonly extent: "current-message";
  readonly rawRetained: false;
}

export interface TranscriptCapture {
  readonly schemaVersion: 1;
  readonly sessionId: string;
  readonly turnId: string;
  readonly hookEventName: TranscriptHookEvent;
  readonly origin: TranscriptOrigin;
  readonly snapshot: TranscriptSnapshot;
  readonly snapshotSha256: string;
}

export type CaptureTranscriptResult =
  | { readonly status: "captured"; readonly capture: TranscriptCapture }
  | { readonly status: "rejected"; readonly code: CaptureRejectionCode };

export type TranscriptSinkReceipt =
  | { readonly status: "saved"; readonly receiptId: string; readonly snapshotSha256: string }
  | { readonly status: "failed"; readonly code: string }
  | { readonly status: "unknown"; readonly code: string };

export type TranscriptSink = (capture: Readonly<TranscriptCapture>) => Promise<TranscriptSinkReceipt>;

export type TranscriptJobState = "queued" | "saving" | "saved" | "failed" | "unknown";

export interface TranscriptJobStatus {
  readonly jobId: number;
  readonly status: TranscriptJobState;
  readonly snapshotSha256: string;
  readonly receiptId?: string;
  readonly code?: string;
}

export type TranscriptEnqueueResult =
  | { readonly status: "queued"; readonly jobId: number }
  | { readonly status: "queue_full" | "closed" | "invalid_capture" };

export interface TranscriptQueueOptions {
  readonly sink: TranscriptSink;
  /** Maximum in-flight plus waiting jobs. Defaults to 32; accepted range is 1..64. */
  readonly maxPending?: number;
}

export interface TranscriptQueue {
  enqueue(capture: TranscriptCapture): TranscriptEnqueueResult;
  getStatus(jobId: number): TranscriptJobStatus | undefined;
  readRecentStatuses(limit?: number): readonly TranscriptJobStatus[];
  drain(): Promise<void>;
  close(): Promise<void>;
}

/** Capture the one current Hook message while its transient JSONL still exists. */
export function captureTranscript(input: CaptureTranscriptInput): CaptureTranscriptResult {
  try {
    const normalized = validateCaptureInput(input);
    const read = readOwnedTranscript(normalized.ownedTempRoot, normalized.hookInput.transcriptPath);
    const record = parseTranscriptRecord(read.bytes);
    const expectedRole = normalized.hookInput.hookEventName === "UserPromptSubmit" ? "user" : "assistant";
    const expectedText = normalized.hookInput.hookEventName === "UserPromptSubmit"
      ? normalized.hookInput.prompt
      : normalized.hookInput.responseText ?? normalized.hookInput.responsePreview;
    if (record.role !== expectedRole || expectedText === undefined || record.text !== expectedText) {
      throw new CaptureFailure("message_mismatch");
    }

    const message: TranscriptMessageSnapshot = Object.freeze({
      role: expectedRole,
      text: "[REDACTED]",
      textBytes: Buffer.byteLength(record.text, "utf8"),
      textSha256: sha256(Buffer.from(record.text, "utf8")),
    });
    const snapshot: TranscriptSnapshot = Object.freeze({
      schemaVersion: 1,
      redactionVersion: "full-mask-v1",
      messages: Object.freeze([message]),
    });
    const rootRelativePath = path.relative(normalized.ownedTempRoot, normalized.transcriptPath);
    const temporaryLocator = rootRelativePath.split(path.sep).join("/");
    const origin: TranscriptOrigin = Object.freeze({
      temporaryLocator,
      locatorUse: "historical-only",
      rawBytes: read.bytes.byteLength,
      rawSha256: sha256(read.bytes),
      sourcePin: normalized.sourcePin,
      extent: "current-message",
      rawRetained: false,
    });
    const capture: TranscriptCapture = Object.freeze({
      schemaVersion: 1,
      sessionId: normalized.hookInput.sessionId,
      turnId: normalized.hookInput.turnId,
      hookEventName: normalized.hookInput.hookEventName,
      origin,
      snapshot,
      snapshotSha256: snapshotSha256(snapshot),
    });
    return Object.freeze({ status: "captured", capture });
  } catch (error) {
    return Object.freeze({ status: "rejected", code: rejectionCode(error) });
  }
}

/** A bounded, single-writer queue; enqueue never waits for sink work. */
export function createTranscriptQueue(options: TranscriptQueueOptions): TranscriptQueue {
  if (!isPlainRecord(options) || typeof options.sink !== "function") {
    throw new TypeError("transcript queue requires a sink function");
  }
  const maxPending = options.maxPending ?? DEFAULT_MAX_PENDING;
  if (!Number.isSafeInteger(maxPending) || maxPending < 1 || maxPending > STATUS_LIMIT) {
    throw new RangeError("transcript queue maxPending must be an integer from 1 through 64");
  }

  let closed = false;
  let pumping = false;
  let pumpScheduled = false;
  let nextJobId = 1;
  const waiting: QueueJob[] = [];
  const pending = new Map<number, QueueJob>();
  const statuses = new Map<number, TranscriptJobStatus>();
  const setStatus = (status: TranscriptJobStatus): void => {
    statuses.set(status.jobId, Object.freeze({ ...status }));
    while (statuses.size > STATUS_LIMIT) {
      const oldest = statuses.keys().next().value as number | undefined;
      if (oldest === undefined) break;
      statuses.delete(oldest);
    }
  };

  const schedulePump = (): void => {
    if (pumping || pumpScheduled) return;
    pumpScheduled = true;
    queueMicrotask(() => {
      pumpScheduled = false;
      void pump();
    });
  };

  const pump = async (): Promise<void> => {
    if (pumping) return;
    pumping = true;
    try {
      while (waiting.length > 0) {
        const job = waiting.shift();
        if (!job) continue;
        setStatus({ jobId: job.jobId, status: "saving", snapshotSha256: job.capture.snapshotSha256 });
        let terminal: TranscriptJobStatus;
        try {
          terminal = resolveSinkReceipt(job, await options.sink(job.capture));
        } catch {
          terminal = { jobId: job.jobId, status: "unknown", snapshotSha256: job.capture.snapshotSha256, code: "sink_threw" };
        }
        setStatus(terminal);
        pending.delete(job.jobId);
        job.resolveSettled();
      }
    } finally {
      pumping = false;
      if (waiting.length > 0) schedulePump();
    }
  };

  const drain = (): Promise<void> => {
    const acceptedFrontier = [...pending.values()].map((job) => job.settled);
    return acceptedFrontier.length === 0 ? Promise.resolve() : Promise.all(acceptedFrontier).then(() => undefined);
  };

  return Object.freeze({
    enqueue(capture: TranscriptCapture): TranscriptEnqueueResult {
      if (closed) return Object.freeze({ status: "closed" });
      if (pending.size >= maxPending) return Object.freeze({ status: "queue_full" });
      const snapshot = copyValidatedCapture(capture);
      if (!snapshot) return Object.freeze({ status: "invalid_capture" });
      const jobId = nextJobId;
      if (!Number.isSafeInteger(jobId)) throw new RangeError("transcript queue job id space exhausted");
      nextJobId += 1;
      let resolveSettled!: () => void;
      const settled = new Promise<void>((resolve) => { resolveSettled = resolve; });
      const job: QueueJob = { jobId, capture: snapshot, settled, resolveSettled };
      pending.set(jobId, job);
      waiting.push(job);
      setStatus({ jobId, status: "queued", snapshotSha256: snapshot.snapshotSha256 });
      schedulePump();
      return Object.freeze({ status: "queued", jobId });
    },
    getStatus(jobId: number): TranscriptJobStatus | undefined {
      return statuses.get(jobId);
    },
    readRecentStatuses(limit = STATUS_LIMIT): readonly TranscriptJobStatus[] {
      if (!Number.isSafeInteger(limit) || limit < 0 || limit > STATUS_LIMIT) {
        throw new RangeError("transcript status read limit must be an integer from 0 through 64");
      }
      return Object.freeze(limit === 0 ? [] : [...statuses.values()].slice(-limit));
    },
    drain,
    async close(): Promise<void> {
      closed = true;
      await drain();
    },
  });
}

interface NormalizedCaptureInput {
  readonly hookInput: TranscriptHookInput;
  readonly ownedTempRoot: string;
  readonly transcriptPath: string;
  readonly sourcePin: string;
}

interface ReadTranscriptResult {
  readonly bytes: Buffer;
}

interface ParsedTranscriptRecord {
  readonly role: "user" | "assistant";
  readonly text: string;
}

interface QueueJob {
  readonly jobId: number;
  readonly capture: TranscriptCapture;
  readonly settled: Promise<void>;
  readonly resolveSettled: () => void;
}

class CaptureFailure extends Error {
  constructor(readonly code: CaptureRejectionCode) {
    super(code);
  }
}

function validateCaptureInput(input: unknown): NormalizedCaptureInput {
  if (!isPlainRecord(input) || !hasExactKeys(input, ["hookInput", "trace", "ownedTempRoot", "sourcePin"])) {
    throw new CaptureFailure("invalid_input");
  }
  const hook = input.hookInput;
  const trace = input.trace;
  if (!isPlainRecord(hook) || !isPlainRecord(trace) ||
      typeof input.ownedTempRoot !== "string" || !path.isAbsolute(input.ownedTempRoot) ||
      typeof input.sourcePin !== "string" || input.sourcePin.length === 0 || input.sourcePin.length > 256 ||
      /[\u0000-\u001f\u007f]/u.test(input.sourcePin)) {
    throw new CaptureFailure("invalid_input");
  }

  const event = hook.hookEventName;
  const commonKeys = ["hookEventName", "sessionId", "turnId", "transcriptPath"];
  let validMessage = false;
  if (event === "UserPromptSubmit") {
    validMessage = hasExactKeys(hook, [...commonKeys, "prompt"]) && typeof hook.prompt === "string";
  } else if (event === "Stop") {
    const keys = Object.keys(hook);
    validMessage = keys.every((key) => [...commonKeys, "responseText", "responsePreview"].includes(key)) &&
      commonKeys.every((key) => Object.hasOwn(hook, key)) &&
      (hook.responseText === undefined || typeof hook.responseText === "string") &&
      (hook.responsePreview === undefined || typeof hook.responsePreview === "string") &&
      (typeof hook.responseText === "string" || typeof hook.responsePreview === "string");
  }
  if (!validMessage || !hasExactKeys(trace, ["hookEventName", "sessionId", "turnId"])) {
    throw new CaptureFailure("invalid_input");
  }
  if (event !== "UserPromptSubmit" && event !== "Stop") throw new CaptureFailure("invalid_input");
  for (const key of ["sessionId", "turnId", "transcriptPath"] as const) {
    if (typeof hook[key] !== "string" || hook[key].length === 0 || /[\u0000-\u001f\u007f]/u.test(hook[key] as string)) {
      throw new CaptureFailure("invalid_input");
    }
  }
  if (typeof trace.hookEventName !== "string" || typeof trace.sessionId !== "string" || typeof trace.turnId !== "string") {
    throw new CaptureFailure("invalid_input");
  }
  if (trace.hookEventName !== event || trace.sessionId !== hook.sessionId || trace.turnId !== hook.turnId) {
    throw new CaptureFailure("trace_mismatch");
  }
  if (typeof hook.transcriptPath !== "string" || !path.isAbsolute(hook.transcriptPath)) {
    throw new CaptureFailure("invalid_input");
  }

  const hookInput = event === "UserPromptSubmit"
    ? Object.freeze({
        hookEventName: event,
        sessionId: hook.sessionId as string,
        turnId: hook.turnId as string,
        transcriptPath: hook.transcriptPath,
        prompt: hook.prompt as string,
      })
    : Object.freeze({
        hookEventName: event,
        sessionId: hook.sessionId as string,
        turnId: hook.turnId as string,
        transcriptPath: hook.transcriptPath,
        ...(typeof hook.responseText === "string" ? { responseText: hook.responseText } : {}),
        ...(typeof hook.responsePreview === "string" ? { responsePreview: hook.responsePreview } : {}),
      });
  return Object.freeze({
    hookInput,
    ownedTempRoot: path.resolve(input.ownedTempRoot),
    transcriptPath: path.resolve(hook.transcriptPath),
    sourcePin: input.sourcePin,
  });
}

function readOwnedTranscript(ownedTempRoot: string, transcriptPath: string): ReadTranscriptResult {
  let descriptor: number | undefined;
  try {
    const rootRealPath = realpathSync(ownedTempRoot);
    const rootStats = lstatSync(rootRealPath);
    if (!rootStats.isDirectory()) throw new CaptureFailure("not_regular_file");
    const relative = path.relative(ownedTempRoot, transcriptPath);
    if (!isContainedPath(ownedTempRoot, transcriptPath) || relative.length === 0) {
      throw new CaptureFailure("outside_owned_temp");
    }
    const segments = relative.split(path.sep);
    if (segments.some((segment) => segment.length === 0 || segment === "." || segment === "..")) {
      throw new CaptureFailure("outside_owned_temp");
    }

    let current = rootRealPath;
    for (let index = 0; index < segments.length; index += 1) {
      current = path.join(current, segments[index]!);
      const stats = lstatSync(current);
      if (stats.isSymbolicLink()) throw new CaptureFailure("linked_path");
      const last = index === segments.length - 1;
      if (last ? !stats.isFile() : !stats.isDirectory()) throw new CaptureFailure("not_regular_file");
    }
    const realFilePath = realpathSync(current);
    if (!isContainedPath(rootRealPath, realFilePath)) throw new CaptureFailure("outside_owned_temp");

    const flags = constants.O_RDONLY | (typeof constants.O_NOFOLLOW === "number" ? constants.O_NOFOLLOW : 0);
    descriptor = openSync(realFilePath, flags);
    const before = fstatSync(descriptor);
    if (!before.isFile()) throw new CaptureFailure("not_regular_file");
    if (before.size > MAX_TRANSCRIPT_BYTES) throw new CaptureFailure("too_large");

    const chunks: Buffer[] = [];
    let total = 0;
    while (total <= MAX_TRANSCRIPT_BYTES) {
      const chunk = Buffer.alloc(Math.min(64 * 1024, MAX_TRANSCRIPT_BYTES + 1 - total));
      const bytesRead = readSync(descriptor, chunk, 0, chunk.byteLength, null);
      if (bytesRead === 0) break;
      total += bytesRead;
      if (total > MAX_TRANSCRIPT_BYTES) throw new CaptureFailure("too_large");
      chunks.push(chunk.subarray(0, bytesRead));
    }
    const after = fstatSync(descriptor);
    const pathAfter = lstatSync(realFilePath);
    if (pathAfter.isSymbolicLink()) throw new CaptureFailure("linked_path");
    if (!sameFileVersion(before, after) || !sameFileVersion(after, pathAfter) || total !== after.size) {
      throw new CaptureFailure("unstable_read");
    }
    return { bytes: Buffer.concat(chunks, total) };
  } catch (error) {
    if (error instanceof CaptureFailure) throw error;
    throw new CaptureFailure(fsErrorCode(error));
  } finally {
    if (descriptor !== undefined) closeSync(descriptor);
  }
}

function parseTranscriptRecord(bytes: Buffer): ParsedTranscriptRecord {
  let text: string;
  try {
    text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    throw new CaptureFailure("invalid_utf8");
  }
  if (!text.endsWith("\n")) throw new CaptureFailure("incomplete_line");
  const line = text.slice(0, -1);
  if (line.length === 0 || line.includes("\n") || line.includes("\r")) throw new CaptureFailure("malformed_jsonl");
  let parsed: unknown;
  try {
    parsed = JSON.parse(line) as unknown;
  } catch {
    throw new CaptureFailure("malformed_jsonl");
  }
  if (!isPlainRecord(parsed) || !isPlainRecord(parsed.message) ||
      (parsed.message.role !== "user" && parsed.message.role !== "assistant") ||
      !Array.isArray(parsed.message.content)) {
    throw new CaptureFailure("malformed_jsonl");
  }
  let messageText = "";
  for (const item of parsed.message.content) {
    if (!isPlainRecord(item)) continue;
    if (item.type === "text" && typeof item.text === "string") messageText += item.text;
  }
  return { role: parsed.message.role, text: messageText };
}

function copyValidatedCapture(value: unknown): TranscriptCapture | undefined {
  if (!isPlainRecord(value) || !hasExactKeys(value, [
    "schemaVersion", "sessionId", "turnId", "hookEventName", "origin", "snapshot", "snapshotSha256",
  ]) || value.schemaVersion !== 1 ||
      (value.hookEventName !== "UserPromptSubmit" && value.hookEventName !== "Stop") ||
      !isNonEmptyString(value.sessionId) || !isNonEmptyString(value.turnId) ||
      !isSha256(value.snapshotSha256) || !isPlainRecord(value.origin) || !isPlainRecord(value.snapshot)) {
    return undefined;
  }
  const origin = value.origin;
  const snapshot = value.snapshot;
  if (!hasExactKeys(origin, ["temporaryLocator", "locatorUse", "rawBytes", "rawSha256", "sourcePin", "extent", "rawRetained"]) ||
      !isSafeRelativeLocator(origin.temporaryLocator) || origin.locatorUse !== "historical-only" ||
      !Number.isSafeInteger(origin.rawBytes) || (origin.rawBytes as number) < 0 || (origin.rawBytes as number) > MAX_TRANSCRIPT_BYTES ||
      !isSha256(origin.rawSha256) || !isNonEmptyString(origin.sourcePin) || origin.sourcePin.length > 256 ||
      origin.extent !== "current-message" || origin.rawRetained !== false ||
      !hasExactKeys(snapshot, ["schemaVersion", "redactionVersion", "messages"]) ||
      snapshot.schemaVersion !== 1 || snapshot.redactionVersion !== "full-mask-v1" ||
      !Array.isArray(snapshot.messages) || snapshot.messages.length !== 1) {
    return undefined;
  }
  const message = snapshot.messages[0];
  if (!isPlainRecord(message) || !hasExactKeys(message, ["role", "text", "textBytes", "textSha256"]) ||
      (message.role !== "user" && message.role !== "assistant") ||
      (value.hookEventName === "UserPromptSubmit" ? message.role !== "user" : message.role !== "assistant") ||
      message.text !== "[REDACTED]" || !Number.isSafeInteger(message.textBytes) ||
      (message.textBytes as number) < 0 || !isSha256(message.textSha256)) {
    return undefined;
  }

  const safeMessage: TranscriptMessageSnapshot = Object.freeze({
    role: message.role,
    text: "[REDACTED]",
    textBytes: message.textBytes as number,
    textSha256: message.textSha256,
  });
  const safeSnapshot: TranscriptSnapshot = Object.freeze({
    schemaVersion: 1,
    redactionVersion: "full-mask-v1",
    messages: Object.freeze([safeMessage]),
  });
  const calculatedSnapshotHash = snapshotSha256(safeSnapshot);
  if (calculatedSnapshotHash !== value.snapshotSha256) return undefined;

  const safeOrigin: TranscriptOrigin = Object.freeze({
    temporaryLocator: origin.temporaryLocator,
    locatorUse: "historical-only",
    rawBytes: origin.rawBytes as number,
    rawSha256: origin.rawSha256,
    sourcePin: origin.sourcePin,
    extent: "current-message",
    rawRetained: false,
  });
  return Object.freeze({
    schemaVersion: 1,
    sessionId: value.sessionId,
    turnId: value.turnId,
    hookEventName: value.hookEventName,
    origin: safeOrigin,
    snapshot: safeSnapshot,
    snapshotSha256: calculatedSnapshotHash,
  });
}

function resolveSinkReceipt(job: QueueJob, receipt: unknown): TranscriptJobStatus {
  if (!isPlainRecord(receipt) || typeof receipt.status !== "string") {
    return unknownStatus(job, "invalid_receipt");
  }
  if (receipt.status === "saved" && hasExactKeys(receipt, ["status", "receiptId", "snapshotSha256"]) &&
      isNonEmptyString(receipt.receiptId) && receipt.receiptId.length <= 256 &&
      !/[\u0000-\u001f\u007f]/u.test(receipt.receiptId) && receipt.snapshotSha256 === job.capture.snapshotSha256) {
    return {
      jobId: job.jobId,
      status: "saved",
      snapshotSha256: job.capture.snapshotSha256,
      receiptId: receipt.receiptId,
    };
  }
  if ((receipt.status === "failed" || receipt.status === "unknown") &&
      hasExactKeys(receipt, ["status", "code"]) && isSafeStatusCode(receipt.code)) {
    return {
      jobId: job.jobId,
      status: receipt.status,
      snapshotSha256: job.capture.snapshotSha256,
      code: receipt.code,
    };
  }
  return unknownStatus(job, "invalid_receipt");
}

function unknownStatus(job: QueueJob, code: string): TranscriptJobStatus {
  return { jobId: job.jobId, status: "unknown", snapshotSha256: job.capture.snapshotSha256, code };
}

function rejectionCode(error: unknown): CaptureRejectionCode {
  return error instanceof CaptureFailure ? error.code : fsErrorCode(error);
}

function fsErrorCode(error: unknown): CaptureRejectionCode {
  const code = error !== null && typeof error === "object" && "code" in error
    ? (error as { readonly code?: unknown }).code
    : undefined;
  if (code === "ENOENT") return "missing";
  if (code === "EACCES" || code === "EPERM") return "unreadable";
  return "invalid_input";
}

function sameFileVersion(left: { readonly dev: number; readonly ino: number; readonly size: number; readonly mtimeMs: number; readonly ctimeMs: number },
  right: { readonly dev: number; readonly ino: number; readonly size: number; readonly mtimeMs: number; readonly ctimeMs: number }): boolean {
  return left.dev === right.dev && left.ino === right.ino && left.size === right.size &&
    left.mtimeMs === right.mtimeMs && left.ctimeMs === right.ctimeMs;
}

function isContainedPath(root: string, candidate: string): boolean {
  const relative = path.relative(root, candidate);
  return relative.length > 0 && relative !== ".." && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative);
}

function hasExactKeys(value: Record<string, unknown>, expected: readonly string[]): boolean {
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  return actual.length === wanted.length && actual.every((key, index) => key === wanted[index]);
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value) as unknown;
  return prototype === Object.prototype || prototype === null;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isSha256(value: unknown): value is string {
  return typeof value === "string" && /^[0-9a-f]{64}$/u.test(value);
}

function isSafeRelativeLocator(value: unknown): value is string {
  return typeof value === "string" && value.length > 0 && !value.startsWith("/") && !value.includes("\\") &&
    !value.includes(":") && value.split("/").every((segment) => segment.length > 0 && segment !== "." && segment !== "..");
}

function isSafeStatusCode(value: unknown): value is string {
  return typeof value === "string" && /^[a-z0-9_.-]{1,64}$/iu.test(value);
}

function sha256(bytes: Buffer): string {
  return createHash("sha256").update(bytes).digest("hex");
}

function snapshotSha256(snapshot: TranscriptSnapshot): string {
  return sha256(Buffer.from(canonicalizeJson(snapshot as unknown as JsonValue), "utf8"));
}

import assert from "node:assert/strict";
import test from "node:test";

import {
  canonicalizeEventFacts,
  canonicalizeJson,
  normalizeRuntimeEvent,
  normalizeSourceSequence,
  projectAttempt,
} from "../../../dist/packages/contracts/src/index.js";

const scope = Object.freeze({ sessionId: "session-1", turnId: "turn-1", runId: "run-1", taskId: "task-1" });
const target = Object.freeze({ scope, attemptId: "attempt-1" });
const eventInput = (overrides = {}) => ({
  source: "zcode/pin/session-1",
  eventId: "event-1",
  scope,
  attemptId: "attempt-1",
  operationId: null,
  kind: "fact",
  occurredAt: "2026-10-03T00:00:00.000Z",
  observedAt: "2026-10-03T00:00:01.000Z",
  sourceSequence: 1,
  payload: { nested: { b: 2, a: 1 } },
  ...overrides,
});
const committed = (commitSequence, input) => ({ commitSequence, event: normalizeRuntimeEvent(input) });

test("native source sequence zero becomes unassigned and invalid integers are rejected", () => {
  assert.equal(normalizeSourceSequence(null), null);
  assert.equal(normalizeSourceSequence(0), null);
  assert.equal(normalizeSourceSequence(7), 7);
  for (const invalid of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, Number.NaN, Number.POSITIVE_INFINITY, "1"]) {
    assert.throws(() => normalizeSourceSequence(invalid), /sourceSequence/);
  }
  assert.equal(normalizeRuntimeEvent(eventInput({ sourceSequence: 0 })).sourceSequence, null);
});

test("canonical event facts exclude observation metadata but include occurredAt", () => {
  const first = normalizeRuntimeEvent(eventInput());
  const redelivery = normalizeRuntimeEvent(eventInput({
    observedAt: "2026-10-03T00:10:00.000Z",
    sourceSequence: 9,
    payload: { nested: { a: 1, b: 2 } },
  }));
  assert.equal(canonicalizeEventFacts(first), canonicalizeEventFacts(redelivery));
  assert.notEqual(
    canonicalizeEventFacts(first),
    canonicalizeEventFacts(normalizeRuntimeEvent(eventInput({ occurredAt: "2026-10-03T00:00:02.000Z" }))),
  );
  assert.equal(canonicalizeJson({ b: [2, 1], a: true }), '{"a":true,"b":[2,1]}');
});

test("normalization rejects forged writer fields and snapshots strict JSON input", () => {
  assert.throws(() => normalizeRuntimeEvent({ ...eventInput(), commitSequence: 4 }), /invalid fields/);
  assert.throws(() => normalizeRuntimeEvent({
    ...eventInput(), scope: { ...scope, extra: "foreign" },
  }), /scope has invalid fields/);
  assert.throws(() => normalizeRuntimeEvent(eventInput({ kind: "operation_intent" })), /stable operationId/);
  assert.throws(() => normalizeRuntimeEvent(eventInput({ kind: "operation_receipt" })), /stable operationId/);

  const payload = { nested: { text: "before" } };
  const original = eventInput({ payload });
  const normalized = normalizeRuntimeEvent(original);
  payload.nested.text = "after";
  assert.equal(normalized.payload.nested.text, "before");
  assert.equal(Object.isFrozen(normalized), true);
  assert.equal(Object.isFrozen(normalized.payload), true);
  assert.equal(Object.isFrozen(normalized.payload.nested), true);

  let getterCalled = false;
  const invalidPayload = {};
  Object.defineProperty(invalidPayload, "text", {
    enumerable: true,
    get() { getterCalled = true; return "unsafe"; },
  });
  assert.throws(() => normalizeRuntimeEvent(eventInput({ payload: invalidPayload })), /strict JsonValue/);
  assert.equal(getterCalled, false);
});

test("commit order selects the first terminal despite later source sequence or earlier event time", () => {
  const cancelFirst = committed(20, eventInput({
    eventId: "cancel-first", kind: "cancel", sourceSequence: 40,
    occurredAt: "2026-10-03T00:10:00.000Z", payload: {},
  }));
  const successLater = committed(21, eventInput({
    eventId: "success-later", kind: "success", sourceSequence: 2,
    occurredAt: "2026-10-03T00:01:00.000Z", payload: { response: "must not replace cancel" },
  }));
  const cancelled = projectAttempt([successLater, cancelFirst], target);
  assert.equal(cancelled.lifecycle, "cancel");
  assert.equal(cancelled.terminal.commitSequence, 20);
  assert.equal(cancelled.authoritativeResponse, null);
  assert.ok(cancelled.audit.some((item) => item.kind === "source_sequence_regressed" && item.event.eventId === "success-later"));
  assert.ok(cancelled.audit.some((item) => item.kind === "after_terminal" && item.event.eventId === "success-later"));

  const successFirst = committed(30, eventInput({
    eventId: "success-first", kind: "success", sourceSequence: 2,
    occurredAt: "2026-10-03T00:01:00.000Z", payload: { response: "authoritative" },
  }));
  const cancelLater = committed(31, eventInput({
    eventId: "cancel-later", kind: "cancel", sourceSequence: 40,
    occurredAt: "2026-10-03T00:10:00.000Z", payload: {},
  }));
  const succeeded = projectAttempt([cancelLater, successFirst], target);
  assert.equal(succeeded.lifecycle, "success");
  assert.equal(succeeded.terminal.commitSequence, 30);
  assert.equal(succeeded.authoritativeResponse, "authoritative");
  assert.ok(succeeded.audit.some((item) => item.kind === "after_terminal" && item.event.eventId === "cancel-later"));
});

test("same source and event ID deduplicates facts and audits resequencing without replacing the first", () => {
  const first = committed(1, eventInput({ sourceSequence: 1 }));
  const redelivery = committed(2, eventInput({ observedAt: "2026-10-03T00:03:00.000Z", sourceSequence: 8 }));
  const projected = projectAttempt([first, redelivery], target);
  assert.equal(projected.events.length, 1);
  assert.equal(projected.events[0].sourceSequence, 1);
  assert.ok(projected.audit.some((item) => item.kind === "duplicate"));
  const resequenced = projected.audit.find((item) => item.kind === "redelivery_resequenced");
  assert.equal(resequenced.firstSourceSequence, 1);
  assert.equal(resequenced.observedSourceSequence, 8);
});

test("identity conflict preserves the first fact and cannot seal a turn", () => {
  const first = committed(1, eventInput({ eventId: "collision", kind: "fact", payload: { value: "original" } }));
  const conflicting = committed(2, eventInput({ eventId: "collision", kind: "success", payload: { response: "fabricated" } }));
  const projected = projectAttempt([first, conflicting], target);
  assert.equal(projected.lifecycle, "in_progress");
  assert.equal(projected.events.length, 1);
  assert.equal(projected.events[0].kind, "fact");
  assert.ok(projected.audit.some((item) => item.kind === "identity_conflict" &&
    item.event.source === first.event.source && item.event.scope.turnId === scope.turnId &&
    item.event.attemptId === target.attemptId));
});

test("identity is source plus event ID, while writer sequence collisions reject distinct events", () => {
  const first = committed(1, eventInput({ eventId: "shared" }));
  const anotherSource = committed(2, eventInput({ eventId: "shared", source: "other-runtime/session-1" }));
  assert.equal(projectAttempt([first, anotherSource], target).events.length, 2);
  assert.throws(() => projectAttempt([
    first,
    committed(1, eventInput({ eventId: "different" })),
  ], target), /writer commit sequence collision/);
  assert.throws(() => projectAttempt([
    first,
    committed(1, eventInput({ eventId: "shared", payload: { changed: true } })),
  ], target), /writer commit sequence collision/);
  const sameCommitRedelivery = projectAttempt([
    committed(3, eventInput({ eventId: "same-commit", sourceSequence: 1 })),
    committed(3, eventInput({ eventId: "same-commit", observedAt: "2026-10-03T00:20:00.000Z", sourceSequence: 4 })),
  ], target);
  assert.equal(sameCommitRedelivery.events.length, 1);
  assert.ok(sameCommitRedelivery.audit.some((item) => item.kind === "redelivery_resequenced"));
  assert.throws(() => projectAttempt([
    { commitSequence: 0, event: normalizeRuntimeEvent(eventInput()) },
  ], target), /positive safe integer/);
});

test("scope must bind all IDs; old attempt events remain audit-only", () => {
  assert.throws(() => projectAttempt([], {
    scope: { sessionId: "session-1", turnId: "turn-1", runId: null, taskId: "task-1" },
    attemptId: "attempt-1",
  }), /runId/);
  assert.throws(() => projectAttempt([
    committed(1, eventInput({ scope: { ...scope, taskId: "other-task" } })),
  ], target), /scope does not match/);

  const oldAttemptSuccess = committed(1, eventInput({
    eventId: "old-attempt", attemptId: "attempt-0", kind: "success", payload: { response: "old" },
  }));
  const currentDraft = committed(2, eventInput({ eventId: "current-draft", kind: "draft", payload: { text: "partial" } }));
  const current = projectAttempt([oldAttemptSuccess, currentDraft], target);
  assert.equal(current.lifecycle, "in_progress");
  assert.equal(current.authoritativeResponse, null);
  assert.equal(current.events.length, 1);
  assert.equal(current.drafts.length, 1);
  assert.ok(current.audit.some((item) => item.kind === "old_attempt" && item.event.attemptId === "attempt-0"));
});

test("drafts and failures never become formal replies; operation receipts do not seal turns", () => {
  const draft = committed(1, eventInput({ eventId: "draft", kind: "draft", payload: { response: "half sentence" } }));
  const intent = committed(2, eventInput({
    eventId: "intent", kind: "operation_intent", operationId: "operation-a", payload: { name: "tool-a" },
  }));
  const unknownReceipt = committed(3, eventInput({
    eventId: "receipt", kind: "operation_receipt", operationId: "operation-a", payload: { status: "unknown" },
  }));
  const failure = committed(4, eventInput({ eventId: "failed", kind: "failure", payload: { response: "not official" } }));
  const projected = projectAttempt([draft, intent, unknownReceipt, failure], target);
  assert.equal(projected.lifecycle, "failure");
  assert.equal(projected.authoritativeResponse, null);
  assert.equal(projected.drafts.length, 1);
  assert.equal(projected.events.length, 4);
});

